WITH base AS (SELECT '' AS subject_id,'' AS task_id,'' AS task_incarnation_id,'' AS session_id,'' AS session_incarnation_id,'' AS work_key,'summary' AS coverage_kind,g.period,c.calendar,'requested' AS calendar_basis,c.metric_kind,c.actor_id,c.actor_status,c.actor_kind,c.source,c.model,c.provider,c.agent_client,c.semantics,c.currency,c.input_tokens,c.output_tokens,c.cache_read_tokens,c.cache_write_tokens,c.reasoning_tokens,c.total_tokens,c.source_total_tokens,c.turns,c.cost_subcents,c.rate_tokens,c.input_missing,c.output_missing,c.cache_read_missing,c.cache_write_missing,c.reasoning_missing,c.total_missing,c.source_total_missing,c.turns_missing,c.cost_missing,c.rate_missing,c.token_count,c.cost_count,c.partial_count+CASE WHEN g.month_partial=1 THEN c.token_count+c.cost_count ELSE 0 END AS partial_count,c.estimated_count,c.stale_count,c.cost_basis FROM usage_daily_summaries c JOIN usage_report_calendar g ON g.period=c.usage_date AND g.full_day=1 WHERE  c.scope_id=? AND c.generation=? AND c.calendar=? UNION ALL SELECT u.subject_id,u.task_id,u.task_incarnation_id,u.session_id,u.session_incarnation_id,f.work_key,f.coverage_kind,g.period,? AS calendar,'requested' AS calendar_basis,c.metric_kind,c.actor_id,c.actor_status,c.actor_kind,c.source,c.model,c.provider,c.agent_client,c.semantics,c.currency,c.input_tokens,c.output_tokens,c.cache_read_tokens,c.cache_write_tokens,c.reasoning_tokens,c.total_tokens,c.source_total_tokens,c.turns,c.cost_subcents,c.rate_tokens,CASE WHEN c.metric_kind = 'tokens' AND c.input_tokens IS NULL THEN 1 ELSE 0 END AS input_missing,CASE WHEN c.metric_kind = 'tokens' AND c.output_tokens IS NULL THEN 1 ELSE 0 END AS output_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_read_tokens IS NULL THEN 1 ELSE 0 END AS cache_read_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_write_tokens IS NULL THEN 1 ELSE 0 END AS cache_write_missing,CASE WHEN c.metric_kind = 'tokens' AND c.reasoning_tokens IS NULL THEN 1 ELSE 0 END AS reasoning_missing,CASE WHEN c.metric_kind = 'tokens' AND c.total_tokens IS NULL THEN 1 ELSE 0 END AS total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.source_total_tokens IS NULL THEN 1 ELSE 0 END AS source_total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.turns IS NULL THEN 1 ELSE 0 END AS turns_missing,CASE WHEN c.metric_kind = 'cost' AND c.cost_subcents IS NULL THEN 1 ELSE 0 END AS cost_missing,CASE WHEN c.metric_kind = 'cost' AND c.rate_tokens IS NULL THEN 1 ELSE 0 END AS rate_missing,CASE WHEN c.metric_kind = 'tokens' THEN 1 ELSE 0 END AS token_count,CASE WHEN c.metric_kind = 'cost' THEN 1 ELSE 0 END AS cost_count,CASE WHEN c.partial <> 0 OR (g.month_partial=1) THEN 1 ELSE 0 END AS partial_count,c.estimated AS estimated_count,c.stale AS stale_count,c.cost_basis FROM usage_projection_contributions c JOIN usage_projection_applied a ON a.scope_id=c.scope_id AND a.generation=c.generation AND a.work_key=c.work_key AND a.build_id=c.build_id
 JOIN usage_canonical_facts f ON f.scope_id=c.scope_id AND f.generation=c.generation AND f.build_id=c.build_id AND f.fact_key=c.fact_key
 JOIN usage_subjects u ON u.scope_id=f.scope_id AND u.subject_id=f.subject_id  JOIN usage_report_calendar g ON c.coverage_start>=g.start_at AND c.coverage_start<g.end_at WHERE  c.scope_id=? AND c.generation=? AND c.coverage_kind='point' AND c.calendar='UTC' AND (g.full_day=0 OR (?<>'UTC' AND f.calendar<>?)) UNION ALL SELECT u.subject_id,u.task_id,u.task_incarnation_id,u.session_id,u.session_incarnation_id,f.work_key,f.coverage_kind,c.usage_date AS period,c.calendar,CASE WHEN c.calendar=? THEN 'requested' ELSE 'source' END AS calendar_basis,c.metric_kind,c.actor_id,c.actor_status,c.actor_kind,c.source,c.model,c.provider,c.agent_client,c.semantics,c.currency,c.input_tokens,c.output_tokens,c.cache_read_tokens,c.cache_write_tokens,c.reasoning_tokens,c.total_tokens,c.source_total_tokens,c.turns,c.cost_subcents,c.rate_tokens,CASE WHEN c.metric_kind = 'tokens' AND c.input_tokens IS NULL THEN 1 ELSE 0 END AS input_missing,CASE WHEN c.metric_kind = 'tokens' AND c.output_tokens IS NULL THEN 1 ELSE 0 END AS output_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_read_tokens IS NULL THEN 1 ELSE 0 END AS cache_read_missing,CASE WHEN c.metric_kind = 'tokens' AND c.cache_write_tokens IS NULL THEN 1 ELSE 0 END AS cache_write_missing,CASE WHEN c.metric_kind = 'tokens' AND c.reasoning_tokens IS NULL THEN 1 ELSE 0 END AS reasoning_missing,CASE WHEN c.metric_kind = 'tokens' AND c.total_tokens IS NULL THEN 1 ELSE 0 END AS total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.source_total_tokens IS NULL THEN 1 ELSE 0 END AS source_total_missing,CASE WHEN c.metric_kind = 'tokens' AND c.turns IS NULL THEN 1 ELSE 0 END AS turns_missing,CASE WHEN c.metric_kind = 'cost' AND c.cost_subcents IS NULL THEN 1 ELSE 0 END AS cost_missing,CASE WHEN c.metric_kind = 'cost' AND c.rate_tokens IS NULL THEN 1 ELSE 0 END AS rate_missing,CASE WHEN c.metric_kind = 'tokens' THEN 1 ELSE 0 END AS token_count,CASE WHEN c.metric_kind = 'cost' THEN 1 ELSE 0 END AS cost_count,CASE WHEN c.partial <> 0 OR (c.calendar<>? OR c.coverage_start<? OR c.coverage_end>?) THEN 1 ELSE 0 END AS partial_count,c.estimated AS estimated_count,c.stale AS stale_count,c.cost_basis FROM usage_projection_contributions c JOIN usage_projection_applied a ON a.scope_id=c.scope_id AND a.generation=c.generation AND a.work_key=c.work_key AND a.build_id=c.build_id
 JOIN usage_canonical_facts f ON f.scope_id=c.scope_id AND f.generation=c.generation AND f.build_id=c.build_id AND f.fact_key=c.fact_key
 JOIN usage_subjects u ON u.scope_id=f.scope_id AND u.subject_id=f.subject_id  WHERE  c.scope_id=? AND c.generation=? AND c.coverage_kind NOT IN ('point','lifetime') AND 1=1 AND c.coverage_end>? AND c.coverage_start<? AND (c.calendar<>? OR NOT EXISTS (SELECT 1 FROM usage_report_calendar g WHERE g.period=c.usage_date AND g.full_day=1))) SELECT CASE WHEN SUM(input_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(input_tokens) AS BIGINT) END AS input_tokens,CASE WHEN SUM(output_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(output_tokens) AS BIGINT) END AS output_tokens,CASE WHEN SUM(cache_read_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(cache_read_tokens) AS BIGINT) END AS cache_read_tokens,CASE WHEN SUM(cache_write_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(cache_write_tokens) AS BIGINT) END AS cache_write_tokens,CASE WHEN SUM(reasoning_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(reasoning_tokens) AS BIGINT) END AS reasoning_tokens,CASE WHEN SUM(total_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(total_tokens) AS BIGINT) END AS total_tokens,CASE WHEN SUM(source_total_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(source_total_tokens) AS BIGINT) END AS source_total_tokens,CASE WHEN SUM(turns_missing)=0 AND SUM(token_count)>0 THEN CAST(SUM(turns) AS BIGINT) END AS turns,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' AND currency<>'' THEN currency END)<=1 THEN CASE WHEN SUM(cost_missing)=0 AND SUM(cost_count)>0 THEN CAST(SUM(CASE WHEN currency=(SELECT MIN(currency) FROM base WHERE metric_kind='cost' AND currency<>'') THEN cost_subcents END) AS BIGINT) END END AS cost_subcents,CASE WHEN SUM(rate_missing)=0 AND SUM(cost_count)>0 THEN CAST(SUM(rate_tokens) AS BIGINT) END AS rate_tokens,SUM(input_missing) AS input_missing,SUM(output_missing) AS output_missing,SUM(cache_read_missing) AS cache_read_missing,SUM(cache_write_missing) AS cache_write_missing,SUM(reasoning_missing) AS reasoning_missing,SUM(total_missing) AS total_missing,SUM(source_total_missing) AS source_total_missing,SUM(turns_missing) AS turns_missing,SUM(cost_missing) AS cost_missing,SUM(rate_missing) AS rate_missing,SUM(token_count) AS token_count,SUM(cost_count) AS cost_count,SUM(partial_count) AS partial_count,SUM(estimated_count) AS estimated_count,SUM(stale_count) AS stale_count,CASE WHEN MIN(model)=MAX(model) THEN MIN(model) ELSE 'mixed' END AS model,CASE WHEN MIN(provider)=MAX(provider) THEN MIN(provider) ELSE 'mixed' END AS provider,CASE WHEN MIN(agent_client)=MAX(agent_client) THEN MIN(agent_client) ELSE 'mixed' END AS agent_client,CASE WHEN MIN(calendar)=MAX(calendar) THEN MIN(calendar) ELSE 'mixed' END AS calendar,CASE WHEN MIN(calendar_basis)=MAX(calendar_basis) THEN MIN(calendar_basis) ELSE 'mixed' END AS calendar_basis,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' AND currency<>'' THEN currency END)>1 THEN 'mixed' ELSE COALESCE(MIN(NULLIF(currency,'')),'') END AS currency,CASE WHEN MIN(CASE WHEN metric_kind='cost' THEN cost_basis END)=MAX(CASE WHEN metric_kind='cost' THEN cost_basis END) THEN MIN(CASE WHEN metric_kind='cost' THEN cost_basis END) WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' THEN cost_basis END)>1 THEN 'mixed' ELSE 'unknown' END AS cost_basis,SUM(CASE WHEN metric_kind='tokens' THEN partial_count ELSE 0 END) AS token_partial,SUM(CASE WHEN metric_kind='cost' THEN partial_count ELSE 0 END) AS cost_partial,SUM(CASE WHEN coverage_kind='lifetime' THEN 1 ELSE 0 END) AS undated_count,SUM(CASE WHEN coverage_kind<>'lifetime' THEN 1 ELSE 0 END) AS dated_count,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='tokens' THEN actor_id||':'||actor_status||':'||actor_kind END)=1 THEN COALESCE(MIN(CASE WHEN metric_kind='tokens' THEN actor_id END),'') ELSE '' END AS token_actor_id,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='tokens' THEN actor_id||':'||actor_status||':'||actor_kind END)>1 THEN 'mixed' ELSE COALESCE(MIN(CASE WHEN metric_kind='tokens' THEN actor_status END),'unknown') END AS token_actor_status,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='tokens' THEN actor_id||':'||actor_status||':'||actor_kind END)=1 THEN COALESCE(MIN(CASE WHEN metric_kind='tokens' THEN actor_kind END),'unknown') ELSE 'unknown' END AS token_actor_kind,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='tokens' THEN source END)>1 THEN 'mixed' ELSE COALESCE(MIN(CASE WHEN metric_kind='tokens' THEN source END),'') END AS token_source,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' THEN actor_id||':'||actor_status||':'||actor_kind END)=1 THEN COALESCE(MIN(CASE WHEN metric_kind='cost' THEN actor_id END),'') ELSE '' END AS cost_actor_id,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' THEN actor_id||':'||actor_status||':'||actor_kind END)>1 THEN 'mixed' ELSE COALESCE(MIN(CASE WHEN metric_kind='cost' THEN actor_status END),'unknown') END AS cost_actor_status,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' THEN actor_id||':'||actor_status||':'||actor_kind END)=1 THEN COALESCE(MIN(CASE WHEN metric_kind='cost' THEN actor_kind END),'unknown') ELSE 'unknown' END AS cost_actor_kind,CASE WHEN COUNT(DISTINCT CASE WHEN metric_kind='cost' THEN source END)>1 THEN 'mixed' ELSE COALESCE(MIN(CASE WHEN metric_kind='cost' THEN source END),'') END AS cost_source FROM base HAVING COUNT(*)>0
